        $text | Should -Match 'todoId: BUG-TRIAGE-175'
        $text | Should -Match 'openedAt: 2026-09-23T20:00:00Z'
        $text | Should -Match 'auditDialog: 2'
        $text | Should -Match 'auditActions: 1'
        $text | Should -Match 'degraded: true'
